3	import (
4		"os"
5		"strings"
6		"testing"
7		"time"
8	)
9	
10	// These tests pin the collected_at fractional-second rule at every boundary:
11	//
12	//   - a fraction of at most nine digits is exact and accepted as before;
13	//   - a longer fraction is accepted only when every digit past the ninth is
14	//     zero (".1234567890" is the same instant as ".123456789");
15	//   - any non-zero digit past the ninth rejects the record — Go's time.Parse
16	//     silently truncates such input, merging distinct collection moments
17	//     (".1234567891" and ".1234567892") into one nanosecond instant, which
18	//     would miscount genuinely different records as duplicates;
19	//   - the same rule guards the stored-file read path: a saved file carrying
20	//     an unrepresentable fraction is corruption naming the record and field,
21	//     even when its checksum matches the truncated interpretation.
22	//
23	// Any such failure rejects the whole batch before the first file is written.
24	
25	func TestParseHeartbeatsRejectsFractionBeyondNanoseconds(t *testing.T) {
26		cases := []struct {
27			name  string
28			stamp string
29			frac  string // the offending fraction text the error must quote
30		}{
31			{"tenth digit non-zero", "2026-10-01T11:59:00.1234567891Z", ".1234567891"},
32			{"same prefix, different tenth digit", "2026-10-01T11:59:00.1234567892Z", ".1234567892"},
33			{"eleven digits, last non-zero", "2026-10-01T11:59:00.12345678901Z", ".12345678901"},
34			{"non-zero far past the ninth", "2026-10-01T11:59:00.0000000000001Z", ".0000000000001"},
35			{"non-zero tenth digit with offset", "2026-10-01T11:59:00.1234567891+08:00", ".1234567891"},
36		}
37		receive := testBase
38		for _, tc := range cases {
39			t.Run(tc.name, func(t *testing.T) {
40				input := `[{"node":"n1","seq":1,"collected_at":"` + tc.stamp + `","version":"1.0","height":1,"missed":0}]`
41				records, err := ParseHeartbeats([]byte(input), receive)
42				if err == nil {
43					t.Fatalf("fraction %q must be rejected, not truncated", tc.frac)
44				}
45				if records != nil {
46					t.Errorf("ParseHeartbeats must return no partial records, got %v", records)
47				}
48				msg := err.Error()
49				for _, want := range []string{"record 1", "collected_at", tc.frac, "nanosecond"} {
50					if !strings.Contains(msg, want) {
51						t.Errorf("error %q must mention %q", msg, want)
52					}
53				}
54			})
55		}
56	}
57	
58	// TestParseHeartbeatsRejectsTruncationCollision is the reported regression:
59	// two collection moments that differ only past the ninth fractional digit
60	// must not collapse into one instant. Both records are refused outright —
61	// they may never be silently merged and counted as duplicates.
62	func TestParseHeartbeatsRejectsTruncationCollision(t *testing.T) {
63		input := `[
64		  {"node":"n1","seq":1,"collected_at":"2026-10-01T11:59:00.1234567891Z","version":"1.0","height":1,"missed":0},
65		  {"node":"n1","seq":1,"collected_at":"2026-10-01T11:59:00.1234567892Z","version":"1.0","height":1,"missed":0}
66		]`
67		records, err := ParseHeartbeats([]byte(input), testBase)
68		if err == nil {
69			t.Fatal("records distinguishable only past nanosecond precision must be rejected")
70		}
71		if records != nil {
72			t.Errorf("no partial records may be returned, got %v", records)
73		}
74		if !strings.Contains(err.Error(), "record 1") || !strings.Contains(err.Error(), "collected_at") {
75			t.Errorf("error must locate record 1 and collected_at, got %v", err)
76		}
77	}
78	
79	func TestParseHeartbeatsAcceptsExactFractionForms(t *testing.T) {
80		cases := []struct {
81			name  string
82			stamp string
83			want  time.Time
84		}{
85			{"no fraction", "2026-10-01T11:59:00Z", time.Date(2026, 10, 1, 11, 59, 0, 0, time.UTC)},
86			{"one digit", "2026-10-01T11:59:00.5Z", time.Date(2026, 10, 1, 11, 59, 0, 500000000, time.UTC)},
87			{"nine digits", "2026-10-01T11:59:00.123456789Z", time.Date(2026, 10, 1, 11, 59, 0, 123456789, time.UTC)},
88			{"tenth digit zero", "2026-10-01T11:59:00.1234567890Z", time.Date(2026, 10, 1, 11, 59, 0, 123456789, time.UTC)},
89			{"many trailing zeros", "2026-10-01T11:59:00.12345678900000000Z", time.Date(2026, 10, 1, 11, 59, 0, 123456789, time.UTC)},
90			{"all-zero long fraction", "2026-10-01T11:59:00.0000000000000Z", time.Date(2026, 10, 1, 11, 59, 0, 0, time.UTC)},
91			{"trailing zero with offset", "2026-10-01T11:59:00.1234567890+08:00", time.Date(2026, 10, 1, 11, 59, 0, 123456789, time.FixedZone("", 8*3600))},
92		}
93		for _, tc := range cases {
94			t.Run(tc.name, func(t *testing.T) {
95				receive := time.Date(2026, 10, 2, 0, 0, 0, 0, time.UTC)
96				input := `[{"node":"n1","seq":1,"collected_at":"` + tc.stamp + `","version":"1.0","height":1,"missed":0}]`
97				records, err := ParseHeartbeats([]byte(input), receive)
98				if err != nil {
99					t.Fatalf("exactly representable fraction %q must be accepted, got %v", tc.stamp, err)
100				}
101				if !records[0].CollectedAt.Equal(tc.want) {
102					t.Errorf("decoded instant %v, want %v", records[0].CollectedAt, tc.want)
103				}
104			})
105		}
106	}
107	
108	// TestParseHeartbeatsFractionJSONEscapeEquivalence pins that a time text
109	// spelled with JSON escapes is judged on the decoded string: an escaped
110	// trailing-zero fraction is accepted exactly like its literal form, and an
111	// escaped unrepresentable digit is rejected exactly like its literal form.
112	func TestParseHeartbeatsFractionJSONEscapeEquivalence(t *testing.T) {
113		receive := testBase
114	
115		// "2026-10-01T11:59:00.1234567890Z" with the dot (.) and the
116		// trailing zero (0) escaped: the same instant as the literal form.
117		accepted := `[{"node":"n1","seq":1,"collected_at":"2026-10-01T11:59:00\u002E123456789\u0030Z","version":"1.0","height":1,"missed":0}]`
118		records, err := ParseHeartbeats([]byte(accepted), receive)
119		if err != nil {
120			t.Fatalf("escaped trailing-zero fraction must be accepted: %v", err)
121		}
122		if records[0].CollectedAt.Nanosecond() != 123456789 {
123			t.Errorf("escaped form decoded to %d ns, want 123456789", records[0].CollectedAt.Nanosecond())
124		}
125	
126		// "2026-10-01T11:59:00.1234567891Z" with the tenth digit (1)
127		// escaped: the same rejection as the literal spelling.
128		rejected := `[{"node":"n1","seq":1,"collected_at":"2026-10-01T11:59:00.123456789\u0031Z","version":"1.0","height":1,"missed":0}]`
129		_, err = ParseHeartbeats([]byte(rejected), receive)
130		if err == nil {
131			t.Fatal("escaped unrepresentable fraction must be rejected like the literal form")
132		}
133		if !strings.Contains(err.Error(), "collected_at") || !strings.Contains(err.Error(), ".1234567891") {
134			t.Errorf("error must name collected_at and the decoded fraction, got %v", err)
135		}
136	}
137	
138	// TestSubmitRejectsUnrepresentableFractionWholeBatch mirrors the atomicity
139	// contract for the fraction rule: one record whose collection moment cannot
140	// be represented exactly fails the whole batch — the existing node's file
141	// stays byte-for-byte unchanged, no new node gains telemetry, and a record
142	// whose truncated form would match a saved one is not counted as a duplicate.
143	func TestSubmitRejectsUnrepresentableFractionWholeBatch(t *testing.T) {
144		dir := t.TempDir()
145		store, err := OpenStore(dir)
146		if err != nil {
147			t.Fatal(err)
148		}
149		receive := testBase
150	
151		// "old" already has telemetry, including a record whose saved instant
152		// equals the *truncated* form of the offending record below.
153		existing := hb("old", 1, time.Date(2026, 10, 1, 11, 59, 0, 123456789, time.UTC), "1.0", 100, 0)
154		if _, _, err := store.Submit([]Heartbeat{existing}, receive); err != nil {
155			t.Fatal(err)
156		}
157		oldBefore, err := os.ReadFile(store.nodePath("old"))
158		if err != nil {
159			t.Fatal(err)
160		}
161	
162		// The offending record truncates to the exact saved instant of old seq 1;
163		// it must still be rejected, never counted as a duplicate of it.
164		input := `[
165		  {"node":"fresh","seq":1,"collected_at":"2026-10-01T11:59:30Z","version":"1.0","height":1,"missed":0},
166		  {"node":"old","seq":2,"collected_at":"2026-10-01T11:59:30Z","version":"1.0","height":101,"missed":0},
167		  {"node":"old","seq":1,"collected_at":"2026-10-01T11:59:00.1234567891Z","version":"1.0","height":100,"missed":0}
168		]`
169		records, err := ParseHeartbeats([]byte(input), receive)
170		if err == nil {
171			t.Fatal("batch with an unrepresentable fraction must be rejected at parse")
172		}
173		if records != nil {
174			t.Fatalf("no partial records may be returned, got %v", records)
175		}
176		if !strings.Contains(err.Error(), "record 3") || !strings.Contains(err.Error(), "collected_at") {
177			t.Errorf("error must locate record 3 and collected_at, got %v", err)
178		}
179	
180		// Nothing was submitted, so the store is untouched.
181		if after, rerr := os.ReadFile(store.nodePath("old")); rerr != nil || string(after) != string(oldBefore) {
182			t.Fatalf("existing node file changed: err=%v", rerr)
183		}
184		hist, herr := store.History("fresh")
185		if herr != nil {
186			t.Fatal(herr)
187		}
188		if len(hist) != 0 {
189			t.Errorf("new node gained telemetry despite rejected batch: %+v", hist)
190		}
191		if _, serr := os.Stat(store.nodePath("fresh")); !os.IsNotExist(serr) {
192			t.Errorf("no file may be created for fresh, stat err=%v", serr)
193		}
194	}
195	
196	// TestStoredUnrepresentableFractionFileIsCorrupt forges a node file whose raw
197	// JSON carries a fraction past nanosecond precision, with a checksum matching
198	// the truncated interpretation. History and health must report corruption
199	// naming the record and field, and a submit to that node must refuse the
200	// whole batch without overwriting the file.
201	func TestStoredUnrepresentableFractionFileIsCorrupt(t *testing.T) {
202		dir := t.TempDir()
203		store, err := OpenStore(dir)
204		if err != nil {
205			t.Fatal(err)
206		}
207		path := store.nodePath("n1")
208		tamperedFile(t, path, `[{"node":"n1","seq":1,"collected_at":"2026-10-01T11:59:00.12345678901Z","version":"1.0","height":100,"missed":0}]`)
209		corruptBefore, err := os.ReadFile(path)
210		if err != nil {
211			t.Fatal(err)
212		}
213	
214		_, err = loadNodeFileFor(store, "n1")
215		if err == nil || !IsCorrupt(err) {
216			t.Fatalf("unrepresentable stored fraction must be corruption, got %v", err)
217		}
218		msg := err.Error()
219		for _, want := range []string{"record 1", "collected_at", ".12345678901", "nanosecond"} {
220			if !strings.Contains(msg, want) {
221				t.Errorf("corruption error must mention %q, got %v", want, err)
222			}
223		}
224		if _, err := store.Health("n1", testBase, "1.0", 0); err == nil || !IsCorrupt(err) {
225			t.Errorf("health must refuse the corrupt data, got %v", err)
226		}
227		if _, err := store.History("n1"); err == nil || !IsCorrupt(err) {
228			t.Errorf("history must refuse the corrupt data, got %v", err)
229		}
230	
231		// Submitting to the corrupt node refuses the whole batch and leaves the
232		// file byte-for-byte intact.
233		good := hb("n1", 2, testBase.Add(-time.Minute), "1.0", 101, 0)
234		if _, _, err := store.Submit([]Heartbeat{good}, testBase); err == nil || !IsCorrupt(err) {
235			t.Fatalf("submit to a corrupt node must be refused as corruption, got %v", err)
236		}
237		if after, rerr := os.ReadFile(path); rerr != nil || string(after) != string(corruptBefore) {
238			t.Fatalf("corrupt file was overwritten by the refused submit: err=%v", rerr)
239		}
240	}
241	
242	// TestStoredTrailingZeroFractionFileReads proves the legal long form on disk:
243	// a saved record whose fraction only adds trailing zeros past the ninth digit
244	// denotes an exactly representable instant and stays readable.
245	func TestStoredTrailingZeroFractionFileReads(t *testing.T) {
246		dir := t.TempDir()
247		store, err := OpenStore(dir)
248		if err != nil {
249			t.Fatal(err)
250		}
251		path := store.nodePath("n1")
252		tamperedFile(t, path, `[{"node":"n1","seq":1,"collected_at":"2026-10-01T11:59:00.1234567890Z","version":"1.0","height":100,"missed":0}]`)
253	
254		nf, err := loadNodeFileFor(store, "n1")
255		if err != nil {
256			t.Fatalf("trailing-zero fraction must stay readable, got %v", err)
257		}
258		want := time.Date(2026, 10, 1, 11, 59, 0, 123456789, time.UTC)
259		if len(nf.Records) != 1 || !nf.Records[0].CollectedAt.Equal(want) {
260			t.Fatalf("stored instant changed: %+v", nf.Records)
261		}
262		hist, err := store.History("n1")
263		if err != nil {
264			t.Fatal(err)
265		}
266		if len(hist) != 1 || hist[0].CollectedAt.Nanosecond() != 123456789 {
267			t.Errorf("history lost the nanosecond fraction: %+v", hist)
268		}
269	}
270	
271	// TestSameSeqOneNanosecondApartConflicts pins the other side of the rule:
272	// two legal records for the same node and seq whose collection instants
273	// differ by a single nanosecond are a content conflict, not a duplicate.
274	func TestSameSeqOneNanosecondApartConflicts(t *testing.T) {
275		store, err := OpenStore(t.TempDir())
276		if err != nil {
277			t.Fatal(err)
278		}
279		receive := testBase
280		base := time.Date(2026, 10, 1, 11, 59, 0, 123456789, time.UTC)
281		first := hb("n1", 1, base, "1.0", 100, 0)
282		if _, _, err := store.Submit([]Heartbeat{first}, receive); err != nil {
283			t.Fatal(err)
284		}
285		second := hb("n1", 1, base.Add(time.Nanosecond), "1.0", 100, 0)
286		newC, dupC, err := store.Submit([]Heartbeat{second}, receive)
287		if err == nil {
288			t.Fatal("same node+seq one nanosecond apart must conflict, not dedup")
289		}
290		if newC != 0 || dupC != 0 {
291			t.Errorf("conflicted batch counters must be 0/0, got new=%d dup=%d", newC, dupC)
292		}
293		if !strings.Contains(err.Error(), "conflict") {
294			t.Errorf("error must report a content conflict, got %v", err)
295		}
296		hist, herr := store.History("n1")
297		if herr != nil {
298			t.Fatal(herr)
299		}
300		if len(hist) != 1 || !hist[0].Equal(first) {
301			t.Errorf("original record must survive the conflict: %+v", hist)
302		}
303	}
