14	func main() {
15		command := "demo"
16		if len(os.Args) > 1 {
17			command = os.Args[1]
18		}
19		switch command {
20		case "demo":
21			runDemo()
22		case "version":
23			fmt.Println("edgefleet 0.1.0")
24		case "heartbeat":
25			runHeartbeat(os.Args[2:])
26		case "help", "-h", "--help":
27			usage()
28		default:
29			fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
30			usage()
31			os.Exit(2)
32		}
33	}
34	
35	func usage() {
36		fmt.Println("usage: edgefleet [demo|version|heartbeat|help]")
37		fmt.Println()
38		fmt.Println("commands:")
39		fmt.Println("  demo       run the built-in evaluation demo")
40		fmt.Println("  version    print version")
41		fmt.Println("  heartbeat  receive, store and query real heartbeats")
42		fmt.Println("  help       show this help")
43		fmt.Println()
44		fmt.Println("run 'edgefleet heartbeat --help' for heartbeat input format and storage location")
45	}
46	
47	// defaultDataDir resolves the data directory: --data-dir flag, then the
48	// EDGEFLEET_DATA_DIR environment variable, then ~/.edgefleet.
49	func defaultDataDir() string {
50		if d := os.Getenv("EDGEFLEET_DATA_DIR"); d != "" {
51			return d
52		}
53		home, err := os.UserHomeDir()
54		if err != nil {
55			return ".edgefleet"
56		}
57		return home + "/.edgefleet"
58	}
59	
60	// die prints an error to stderr and exits with status 1.
61	func die(format string, args ...any) {
62		fmt.Fprintf(os.Stderr, "error: "+format+"\n", args...)
63		os.Exit(1)
64	}
65	
66	// parseTime parses an RFC3339 time flag, defaulting to now when empty.
67	func parseTimeFlag(value, flagName string) time.Time {
68		if value == "" {
69			return time.Now()
70		}
71		t, err := time.Parse(time.RFC3339, value)
72		if err != nil {
73			die("invalid %s %q: must be RFC3339 with timezone (e.g. 2026-10-01T12:00:00+08:00)", flagName, value)
74		}
75		return t
76	}
77	
78	func runHeartbeat(args []string) {
79		if len(args) == 0 {
80			heartbeatUsage()
81			return
82		}
83		switch args[0] {
84		case "submit":
85			cmdSubmit(args[1:])
86		case "health":
87			cmdHealth(args[1:])
88		case "history":
89			cmdHistory(args[1:])
90		case "help", "-h", "--help":
91			heartbeatUsage()
92		default:
93			fmt.Fprintf(os.Stderr, "unknown heartbeat command %q\n", args[0])
94			heartbeatUsage()
95			os.Exit(2)
96		}
97	}
98	
99	func heartbeatUsage() {
100		fmt.Println("usage: edgefleet heartbeat <submit|health|history> [flags]")
101		fmt.Println()
102		fmt.Println("commands:")
103		fmt.Println("  submit   receive heartbeats from stdin as a JSON array")
104		fmt.Println("  health   query node health from its latest telemetry")
105		fmt.Println("  history  list all heartbeats for a node, ascending by seq")
106		fmt.Println()
107		fmt.Println("input format (submit):")
108		fmt.Println("  A JSON array of heartbeat objects; every field is required.")
109		fmt.Println("    node          string   node id (non-empty, any length)")
110		fmt.Println("    seq           integer  sequence number (> 0)")
111		fmt.Println("    collected_at  string   RFC3339 with timezone, e.g. 2026-10-01T12:00:00+08:00")
112		fmt.Println("                           year 0000-9999; numeric offset hour 00-23 and")
113		fmt.Println("                           minute 00-59 on the minute (no seconds); +24:00")
114		fmt.Println("                           and out-of-range minutes like +00:60 are rejected,")
115		fmt.Println("                           not folded; must not be later than receive time;")
116		fmt.Println("                           a fractional second must be exact at nanosecond")
117		fmt.Println("                           precision: more than nine digits is accepted only")
118		fmt.Println("                           when every digit past the ninth is zero, never")
119		fmt.Println("                           truncated or rounded")
120		fmt.Println("    version       string   version (non-empty, valid Unicode text)")
121		fmt.Println("    height        integer  block height (>= 0)")
122		fmt.Println("    missed        integer  cumulative missed duties (>= 0)")
123		fmt.Println()
124		fmt.Println("  example:")
125		fmt.Println(`    [{"node":"val-eu-1","seq":7,"collected_at":"2026-10-01T11:59:00+08:00",`)
126		fmt.Println(`      "version":"1.26.0","height":12345,"missed":0}]`)
127		fmt.Println()
128		fmt.Println("flags:")
129		fmt.Println("  submit   --data-dir DIR        data directory (default: $EDGEFLEET_DATA_DIR or ~/.edgefleet)")
130		fmt.Println("           --receive-time TIME   receive time, RFC3339 (default: now)")
131		fmt.Println("  health   --node ID             node id (required)")
132		fmt.Println("           --expected-version V  expected version (required)")
133		fmt.Println("           --tolerated-misses N  tolerated missed duties, >= 0 (required)")
134		fmt.Println("           --missed-since-seq S  seq of a saved heartbeat used as the")
135		fmt.Println("                                missed-duty baseline (optional, > 0)")
136		fmt.Println("           --at TIME             query time, RFC3339 (default: now)")
137		fmt.Println("           --data-dir DIR        data directory")
138		fmt.Println()
139		fmt.Println("  Without --missed-since-seq the missed-duty alarm uses the cumulative")
140		fmt.Println("  missed count of the latest heartbeat (missed in the output). With it,")
141		fmt.Println("  the alarm counts only missed duties newly recorded between the baseline")
142		fmt.Println("  heartbeat seq S and the latest one; a count strictly greater than")
143		fmt.Println("  --tolerated-misses alarms, equality does not. The output then shows the")
144		fmt.Println("  baseline seq, the baseline cumulative count and the new count. If the")
145		fmt.Println("  cumulative counter decreased between the baseline and the latest record")
146		fmt.Println("  (e.g. after a node reset), the new count is shown as 无法判断 and a")
147		fmt.Println("  累计漏签数回退 finding is reported; the baseline must name an existing")
148		fmt.Println("  saved seq, otherwise the command fails.")
149		fmt.Println()
150		fmt.Println("  In health output, a node id or version containing whitespace, quotes,")
151		fmt.Println("  backslashes or control characters is shown as a quoted JSON string")
152		fmt.Println("  (newlines as \\n, tabs as \\t, other control characters as \\uXXXX),")
153		fmt.Println("  so every result stays on its own line; the stored text is unchanged.")
154		fmt.Println()
155		fmt.Println("  history  --node ID             node id (required)")
156		fmt.Println("           --data-dir DIR        data directory")
157		fmt.Println()
158		fmt.Println("data storage:")
159		fmt.Println("  One file per node under <data-dir>:")
160		fmt.Println("    nodes/<hex-node-id>.json for short node ids")
161		fmt.Println("    slots/<sha256-node-id>.json for ids too long for a file name")
162		fmt.Println("  A node id of any length is stored and queried by its full text;")
163		fmt.Println("  long ids are never rejected, truncated or renamed.")
164		fmt.Println("  Writes are atomic and the directory is locked for concurrent access.")
165		fmt.Println("  Corrupt data is refused, never silently cleared.")
166	}
167	
168	func newFlagSet(name string) *flag.FlagSet {
169		fs := flag.NewFlagSet(name, flag.ContinueOnError)
170		fs.SetOutput(os.Stderr)
171		fs.Usage = func() { heartbeatUsage() }
172		return fs
173	}
174	
175	func cmdSubmit(args []string) {
176		fs := newFlagSet("heartbeat submit")
177		dataDir := fs.String("data-dir", defaultDataDir(), "data directory")
178		receiveStr := fs.String("receive-time", "", "receive time (RFC3339); default: now")
179		if err := fs.Parse(args); err != nil {
180			if err == flag.ErrHelp {
181				os.Exit(0)
182			}
183			os.Exit(2)
184		}
185		if fs.NArg() != 0 {
186			die("submit takes no positional arguments; heartbeats are read from stdin")
187		}
188	
189		receiveTime := parseTimeFlag(*receiveStr, "--receive-time")
190	
191		data, err := io.ReadAll(os.Stdin)
192		if err != nil {
193			die("cannot read stdin: %v", err)
194		}
195		records, err := edgefleet.ParseHeartbeats(data, receiveTime)
196		if err != nil {
197			die("invalid input: %v", err)
198		}
199	
200		store, err := edgefleet.OpenStore(*dataDir)
201		if err != nil {
202			die("%v", err)
203		}
204		newCount, dupCount, err := store.Submit(records, receiveTime)
205		if err != nil {
206			die("%v", err)
207		}
208		fmt.Printf("submitted: new=%d duplicate=%d\n", newCount, dupCount)
209	}
210	
211	func cmdHealth(args []string) {
212		fs := newFlagSet("heartbeat health")
213		dataDir := fs.String("data-dir", defaultDataDir(), "data directory")
214		node := fs.String("node", "", "node id (required)")
215		atStr := fs.String("at", "", "query time (RFC3339); default: now")
216		expectedVersion := fs.String("expected-version", "", "expected version (required)")
217		toleratedMisses := fs.Int("tolerated-misses", -1, "tolerated missed duties, >= 0 (required)")
218		missedSinceSeq := fs.Int64("missed-since-seq", 0, "seq of a saved heartbeat to use as the missed-duty baseline; must be > 0 and exist for the node")
219		if err := fs.Parse(args); err != nil {
220			if err == flag.ErrHelp {
221				os.Exit(0)
222			}
223			os.Exit(2)
224		}
225		if *node == "" {
226			die("--node is required")
227		}
228		if *expectedVersion == "" {
229			die("--expected-version is required")
230		}
231		if *toleratedMisses < 0 {
232			die("--tolerated-misses is required and must be >= 0")
233		}
234		if isFlagPassed(fs, "missed-since-seq") && *missedSinceSeq <= 0 {
235			die("--missed-since-seq must be a positive integer")
236		}
237	
238		at := parseTimeFlag(*atStr, "--at")
239	
240		store, err := edgefleet.OpenStore(*dataDir)
241		if err != nil {
242			die("%v", err)
243		}
244	
245		var result edgefleet.HealthResult
246		if isFlagPassed(fs, "missed-since-seq") {
247			result, err = store.HealthSince(*node, at, *expectedVersion, *toleratedMisses, *missedSinceSeq)
248		} else {
249			result, err = store.Health(*node, at, *expectedVersion, *toleratedMisses)
250		}
251		if err != nil {
252			die("%v", err)
253		}
254	
255		// Node id and version go through the shared display rule: text that would
256		// break the one-line format (newlines, tabs, quotes, backslashes, control
257		// characters) is shown as a quoted JSON string, so a health query always
258		// prints exactly one line — two with a missed-duty baseline — and node
259		// text can never masquerade as extra fields or a second result line.
260		if result.Status == "notelemetry" {
261			fmt.Printf("node=%s status=无遥测 findings=[无遥测]\n", edgefleet.DisplayText(result.NodeID))
262			return
263		}
264		fmt.Printf("node=%s status=%s seq=%d collected_at=%s version=%s height=%d missed=%d findings=%v\n",
265			edgefleet.DisplayText(result.NodeID), result.Status, result.Seq, result.CollectedAt.Format(time.RFC3339),
266			edgefleet.DisplayText(result.Version), result.Height, result.Missed, result.Findings)
267		if isFlagPassed(fs, "missed-since-seq") {
268			// missed above stays cumulative; this line states the alarm basis.
269			if result.NewMissedKnown {
270				fmt.Printf("baseline_seq=%d baseline_missed=%d new_missed=%d tolerated_misses=%d\n",
271					result.BaselineSeq, result.BaselineMissed, result.NewMissed, *toleratedMisses)
272			} else {
273				fmt.Printf("baseline_seq=%d baseline_missed=%d new_missed=无法判断 tolerated_misses=%d\n",
274					result.BaselineSeq, result.BaselineMissed, *toleratedMisses)
275			}
276		}
277	}
278	
279	// isFlagPassed reports whether the named flag was explicitly set on the
280	// command line, so an optional flag with a zero default can be distinguished
281	// from its absence.
282	func isFlagPassed(fs *flag.FlagSet, name string) bool {
283		passed := false
284		fs.Visit(func(f *flag.Flag) {
285			if f.Name == name {
286				passed = true
287			}
288		})
289		return passed
290	}
291	
292	func cmdHistory(args []string) {
293		fs := newFlagSet("heartbeat history")
294		dataDir := fs.String("data-dir", defaultDataDir(), "data directory")
295		node := fs.String("node", "", "node id (required)")
296		if err := fs.Parse(args); err != nil {
297			if err == flag.ErrHelp {
298				os.Exit(0)
299			}
300			os.Exit(2)
301		}
302		if *node == "" {
303			die("--node is required")
304		}
305	
306		store, err := edgefleet.OpenStore(*dataDir)
307		if err != nil {
308			die("%v", err)
309		}
310		records, err := store.History(*node)
311		if err != nil {
312			die("%v", err)
313		}
314		if len(records) == 0 {
315			fmt.Printf("node=%s no heartbeats\n", *node)
316			return
317		}
318		for _, r := range records {
319			fmt.Printf("node=%s seq=%d collected_at=%s version=%s height=%d missed=%d\n",
320				r.NodeID, r.Seq, r.CollectedAt.Format(time.RFC3339), r.Version, r.Height, r.Missed)
321		}
322	}
323	
324	func runDemo() {
325		nodes := []edgefleet.Node{
326			{ID: "val-eu-1", Region: "eu", Version: "1.26.0", Online: true},
327			{ID: "val-us-1", Region: "us", Version: "1.25.4", Online: true, Missed: 3},
328			{ID: "edge-ap-1", Region: "ap", Version: "1.26.0", Online: false},
329		}
330		unhealthy := 0
331		for _, node := range nodes {
332			health := edgefleet.Evaluate(node, "1.26.0", 1)
333			if !health.Healthy {
334				unhealthy++
335			}
336			fmt.Printf("node=%s healthy=%v findings=%v\n", health.Node, health.Healthy, health.Findings)
337		}
338		fmt.Println("rollout order:", edgefleet.Plan(nodes, "1.26.0"))
339		fmt.Printf("summary: %d of %d nodes need attention\n", unhealthy, len(nodes))
340	}
